// AUDIT 2026-09-11 | IS LISTESI KULLIYATIN TAMAMI OLDU.
//
// ONCE: repos_current.csv okunuyordu - onu readme_v2.py surucusu her turda
// yaziyordu. O surucu ARTIK YOK ve dosya 07.09'dan kalma 790 repoluk bir
// artik. Aylik tazeleme onu okusaydi kulliyatin %3,2'sini tazeler, geri
// kalanini SESSIZCE bayat birakirdi.
//
// SIMDI: DS21tarihce0001'in okudugu AYNI bes dosya - tek kulliyat tanimi.
const fs = require('fs');
const GIRDI = '/data/ds21final/input/';
const cikti = [];
for (let i = 1; i <= 5; i++) {
  const yol = GIRDI + 'repos_meta' + i + '.csv';
  if (!fs.existsSync(yol)) { continue; }
  const satirlar = fs.readFileSync(yol, 'utf8').split('\n');
  for (let k = 1; k < satirlar.length; k++) {
    const s = satirlar[k].trim();
    if (!s) { continue; }
    const p = s.split(',');
    const ad = p[0];
    if (!ad || ad.indexOf('/') < 0) { continue; }
    cikti.push({ json: { full_name: ad, safe_name: ad.replace('/', '__') } });
  }
}
console.log('kulliyat=' + cikti.length);
return cikti;

// NOT 2026-09-11 | VARLIK-TABANLI ONBELLEK BU TASARIMDA DOGRU.
// swap_readmes.py hazirlik klasorunu TASIYARAK bosaltir, yani her aylik
// tur BOS klasorle baslar ve kulliyatin TAMAMI cekilir. Yas kontrolu
// gereksiz. raw.githubusercontent.com kota uygulamiyor (API degil).
// ⚠️ Klasor bosaltilmazsa bu dugum HER SEYI atlar ve tur bos gecer -
// aylik zincirin ilk adimi bu yuzden swap'tir, son adimi degil.
// DEVAM EDEBILIRLIK MEKANIZMASININ TAMAMI BU DUGUM.
// Diskte zaten .md dosyasi olan repolari listeden duser. Boylece calisma
// yarida kesilse bile yeniden baslatmak yalnizca eksikleri ceker; 19.527
// repoluk kademe 2'yi guvenle birakip gitmeyi mumkun kilan sey budur.
const fs = require('fs');
const KLASOR = '/data/ds21final/readme';

let mevcut = new Set();
try {
  mevcut = new Set(
    fs.readdirSync(KLASOR)
      .filter(function (f) { return f.endsWith('.md'); })
      .map(function (f) { return f.slice(0, -3); })
  );
} catch (e) {
  // Klasor yoksa hic dosya yok demektir; bu bir hata degil.
}

const hepsi = $input.all();
const kalan = hepsi.filter(function (it) {
  return !mevcut.has(it.json.safe_name);
});

console.log('toplam=' + hepsi.length + ' onbellek=' + mevcut.size + ' cekilecek=' + kalan.length);

// Ilerlemeyi diske de yaz: basari verisi saklanmadigi icin (saveDataSuccess=none)
// calisma sonrasi geriye donup bakabilecegimiz tek yer dosyalar.
try {
  fs.writeFileSync('/data/ds21final/logs/_son_calisma_baslangic.json', JSON.stringify({
    an: new Date().toISOString(),
    toplam: hepsi.length,
    onbellekte: mevcut.size,
    cekilecek: kalan.length
  }, null, 2));
} catch (e) {}

return kalan;

// Zincirin uc adimi da 404 dondu. Repoyu kayip defterine yaz.
// Sessiz kayip en tehlikeli sonuctur; bu dosya olmadan kac repoyu
// kacirdigimizi asla ogrenemeyiz.
const fs = require('fs');
const DEFTER = '/data/ds21final/logs/misses.jsonl';

const satirlar = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const it = items[i];
  let full_name = it.json && it.json.full_name ? it.json.full_name : null;
  let safe_name = it.json && it.json.safe_name ? it.json.safe_name : null;

  // Hata ciktisinda json korunur; yine de esli ogeden dogrulamayi deniyoruz.
  if (!full_name) {
    try {
      const esli = $('Gruplara Bol').all()[i];
      if (esli && esli.json) {
        full_name = esli.json.full_name;
        safe_name = esli.json.safe_name;
      }
    } catch (e) {}
  }

  satirlar.push(JSON.stringify({
    an: new Date().toISOString(),
    full_name: full_name,
    safe_name: safe_name,
    hata: (function () {
      const e = it.json ? it.json.error : null;
      if (!e) return null;
      if (typeof e === 'string') return e.slice(0, 200);
      // Hata bir NESNE gelir; String() onu '[object Object]' yapar ve
      // kayip defteri hicbir sey soylemez. 404 mu 429 mu ayirt edebilmek
      // buyuk calismada kisitlamayi (throttling) fark etmenin tek yolu.
      const kisa = { mesaj: e.message || null, status: e.status || e.httpCode || null };
      try { return JSON.stringify(kisa).slice(0, 300); } catch (x) { return String(e); }
    })()
  }));
}

if (satirlar.length) {
  fs.appendFileSync(DEFTER, satirlar.join('\n') + '\n');
}

return items;

// ============================================================
// BU DUGUM HER GRUPTA BIR KEZ TETIKLENIR (iki geri donus yolu var),
// BU YUZDEN ICI UCUZ OLMAK ZORUNDA.
//
// Onceki surum diskteki HER dosyaya stat cagiriyordu. Windows bind mount
// uzerinde (gRPC-FUSE) 8.900 dosyalik bir dizin listesi tek basina ~6.5 sn
// suruyor; bu grup basina tekrarlaninca maliyet O(grup x dosya) oluyor ve
// olculen cekim hizi 5.3 -> 0.3 repo/sn'ye dustu. Yani yavaslamanin sebebi
// GitHub kisitlamasi degil, bu sayimdi (tum kayiplar 404, hic 403/429 yok).
//
// Sayim artik host tarafinda verify_readmes.py icinde yapiliyor: orada
// yerel NTFS hizinda calisiyor ve dongude degil, bir kez.
// ============================================================
const fs = require('fs');
const rapor = {
  an: new Date().toISOString(),
  not: 'Dosya sayimi host tarafinda yapilir: scripts/verify_readmes.py'
};
fs.writeFileSync('/data/ds21final/logs/_son_rapor.json', JSON.stringify(rapor, null, 2));
return [{ json: rapor }];
